def transform(grid):
    out = [row[:] for row in grid]
    r, c = next((i, j) for i, row in enumerate(grid)
                for j, value in enumerate(row) if value == 3)
    directions = [(-1, 0), (0, 1), (1, 0), (0, -1)]
    length = 2

    for segment in range(100):
        dr, dc = directions[segment % 4]
        for _ in range(length):
            r += dr
            c += dc
            if 0 <= r < len(out) and 0 <= c < len(out[0]):
                if out[r][c] == 2:
                    return out
                out[r][c] = 3
        if segment % 2 == 1:
            length += 2

    return out
